<template>
  <Teleport to="body">
    <section v-if="store.open" ref="layer" class="immersive-layer" :style="visualVars">
      <svg class="ink-mask" aria-hidden="true"><defs><filter id="ink-rough"><feTurbulence type="fractalNoise" :baseFrequency="visual.inkEdgeFrequency" numOctaves="2"/><feDisplacementMap in="SourceGraphic" scale="16"/></filter></defs><circle :cx="store.origin.x" :cy="store.origin.y" r="1" filter="url(#ink-rough)"/></svg>
      <div class="vignette"/><svg class="herb-shadow" viewBox="0 0 600 600" aria-hidden="true"><path d="M300 550V90m0 130c-116-10-172-70-192-140m192 198c112-18 166-78 190-148M300 360c-92 8-145 60-166 128m166-82c82 10 132 51 151 110"/></svg>
      <header><button class="exit" aria-label="退出沉浸学习" @click="leave(true)">×</button><p>第 {{ stage }} 关 · {{ store.node?.label }}</p></header>
      <main>
        <AlchemyTaskRunner v-if="store.taskIds.length" :task-ids="store.taskIds" :types="store.selected.map(item => item.type)" :using-mock="store.usingMock" @finished="store.progress = ['资源已入库']"/>
        <section v-else class="dialogue" aria-live="polite">
          <div class="assistant-bubble"><XiaoqiMascot :expression="expression" :animated="store.streaming" :size="42"/><Bubble :content="store.greeting" placement="start" variant="outlined" shape="corner" :typing="false"/></div>
          <Bubble v-if="lastPrompt" class="user-bubble" :content="lastPrompt" placement="end" variant="outlined" shape="corner" :typing="false"/>
          <div v-if="store.reply || store.streaming" class="assistant-bubble"><XiaoqiMascot :expression="expression" :animated="store.streaming" :size="42"/><Bubble :content="store.reply || '小岐正在凝神推演…'" placement="start" variant="outlined" shape="corner" :typing="false" :loading="store.streaming"/></div>
          <p v-if="store.error" class="dialogue-error">{{ store.error }}</p>
          <div v-if="store.recommendations.length" class="recommendations"><p class="section-label">今夜可先备下这些药签</p><div class="recommendation-grid"><button v-for="item in store.recommendations" :key="item.type" class="recommendation" :class="{ selected: selected(item.type) }" @click="store.toggle(item)"><strong>{{ labels[item.type] }}</strong><span>{{ item.reason }}</span><i>{{ selected(item.type) ? '已选' : '选择' }}</i></button></div><button class="confirm" :disabled="!store.selected.length" @click="store.confirm">就按这个来</button></div>
          <div v-if="store.progress.length" class="progress"><span v-for="item in store.progress" :key="item">{{ item }}</span></div>
        </section>
        <div class="assessment-entry"><button @click="beginAssessment">过关考核</button></div>
        <form class="input-row" @submit.prevent="send"><div class="chips"><button v-for="chip in store.chips" :key="chip" type="button" :class="{ active: draft === chip }" @click="ask(chip)">{{ chip }}</button></div><div><input v-model="draft" aria-label="向小岐提问" placeholder="说说你此刻想厘清的地方"/><button type="submit" :disabled="!draft.trim() || store.streaming">送出</button></div></form>
      </main>
    </section>
  </Teleport>
</template>

<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { gsap } from 'gsap'
import { Bubble } from 'vue-element-plus-x'
import { immersiveVisual as visual, resourceTypeLabels as labels } from '../../config/immersive'
import { useImmersiveStore } from '../../stores/immersive'
import XiaoqiMascot, { type XiaoqiExpression } from '../ui/XiaoqiMascot.vue'
import AlchemyTaskRunner from './AlchemyTaskRunner.vue'
const store = useImmersiveStore(); const router = useRouter(); const layer = ref<HTMLElement>(); const draft = ref(''); const lastPrompt = ref(''); const stage = computed(() => store.node?.stage || 1)
const expression = computed<XiaoqiExpression>(() => store.error ? 'encourage' : store.streaming ? 'thinking' : store.recommendations.length ? 'happy' : 'default')
const visualVars = computed(() => ({ '--immersive-vignette-opacity': visual.vignetteOpacity }))
const clip = (radius: number) => `circle(${radius}px at ${store.origin.x}px ${store.origin.y}px)`
const selected = (type: string) => store.selected.some((item) => item.type === type)
const send = () => { const value = draft.value.trim(); if (!value) return; lastPrompt.value = value; draft.value = ''; void store.chat(value) }
const ask = (value: string) => { draft.value = value; send() }
const leave = async (skip = false) => { await nextTick(); const reduced = window.matchMedia?.('(prefers-reduced-motion: reduce)').matches; if (layer.value && !skip && !reduced) await gsap.to(layer.value, { clipPath: clip(1), opacity: 0, duration: visual.transitionMs / 1000, ease: visual.transitionEase }); store.close() }
const beginAssessment = () => { const node = store.node; if (!node) return; store.close(); void router.push({ name: 'assessment', params: { nodeId: node.id }, query: { label: node.label } }) }
watch(() => store.open, async (open) => { if (!open) return; lastPrompt.value = ''; await nextTick(); if (layer.value) gsap.fromTo(layer.value, { clipPath: clip(1), opacity: .68 }, { clipPath: clip(Math.hypot(window.innerWidth, window.innerHeight) * 1.1), opacity: 1, duration: visual.transitionMs / 1000, ease: visual.transitionEase }) })
</script>

<style scoped lang="scss">
.immersive-layer{position:fixed;z-index:1000;inset:0;isolation:isolate;overflow:auto;color:var(--qh-text);background:var(--qh-color-night);clip-path:circle(0 at 50% 50%)}.ink-mask{position:absolute;width:0;height:0}.vignette{position:fixed;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 43%,transparent 44%,color-mix(in srgb,var(--qh-color-ink) var(--immersive-vignette-opacity),transparent) 100%)}.herb-shadow{position:absolute;right:-90px;bottom:-130px;width:min(62vw,670px);fill:none;stroke:var(--qh-color-jade);stroke-width:3;opacity:.06;transform:rotate(-12deg)}header{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:center;padding:var(--qh-space-5) 5vw;border-bottom:1px solid var(--qh-border)}header p{margin:0;color:var(--qh-color-gold);font-size:12px;letter-spacing:1.7px}.exit{display:grid;width:34px;height:34px;place-items:center;border:1px solid var(--qh-border);border-radius:50%;color:var(--qh-text);background:color-mix(in srgb,var(--qh-color-night-soft) 78%,transparent);font-size:20px;cursor:pointer}main{position:relative;display:grid;grid-template-rows:1fr auto auto;max-width:1080px;min-height:calc(100vh - 78px);margin:auto;padding:var(--qh-space-8) 5vw var(--qh-space-5)}.dialogue{width:min(760px,100%);display:grid;align-content:start;gap:var(--qh-space-3)}.assistant-bubble{display:grid;grid-template-columns:42px minmax(0,1fr);gap:var(--qh-space-3);align-items:start}.dialogue :deep(.el-bubble){max-width:100%}.dialogue :deep(.el-bubble-content){color:var(--qh-text);border-color:color-mix(in srgb,var(--qh-color-jade) 34%,transparent);background:color-mix(in srgb,var(--qh-color-jade) 12%,transparent);box-shadow:var(--qh-inner-highlight);line-height:1.75}.user-bubble{justify-self:end;width:min(72%,520px)}.user-bubble :deep(.el-bubble-content){border-color:var(--qh-color-jade);background:color-mix(in srgb,var(--qh-color-blue) 11%,transparent)}.dialogue-error{margin:0 0 0 54px;color:var(--qh-color-coral);font-size:13px}.recommendations,.progress{margin-left:54px}.section-label{margin:var(--qh-space-2) 0;color:var(--qh-color-gold);font-size:12px}.recommendation-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--qh-space-2)}.recommendation{display:grid;min-height:138px;padding:var(--qh-space-3);border:1px solid var(--qh-border);border-radius:var(--qh-radius-stage);color:var(--qh-text);background:color-mix(in srgb,var(--qh-color-night-soft) 76%,transparent);text-align:left;cursor:pointer}.recommendation.selected{border-color:var(--qh-color-jade);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--qh-color-jade) 24%,transparent)}.recommendation strong{color:var(--qh-color-cream);font-size:14px}.recommendation span{color:var(--qh-text-muted);font-size:12px;line-height:1.55}.recommendation i{color:var(--qh-color-jade);font-size:11px;font-style:normal}.confirm,.assessment-entry button{margin-top:var(--qh-space-3);padding:11px 19px;border:1px solid var(--qh-color-gold);border-radius:var(--qh-radius-stage);color:var(--qh-color-ink);background:var(--qh-color-gold);font-weight:800;cursor:pointer}.confirm:disabled{opacity:.45}.progress{display:grid;gap:6px;color:var(--qh-text-muted);font-size:12px}.assessment-entry{width:min(760px,100%);margin:var(--qh-space-4) 0 0}.input-row{align-self:end;width:min(760px,100%);margin-top:var(--qh-space-4);padding:var(--qh-space-2);border:1px solid var(--qh-border);border-radius:var(--qh-radius-card-sm);background:color-mix(in srgb,var(--qh-color-night-soft) 72%,transparent);box-shadow:var(--qh-inner-highlight);backdrop-filter:blur(18px)}.chips{display:flex;flex-wrap:wrap;gap:var(--qh-space-2);margin-bottom:var(--qh-space-2)}.chips button{padding:6px 11px;border:1px solid color-mix(in srgb,var(--qh-color-cream) 30%,transparent);border-radius:var(--qh-radius-pill);color:var(--qh-text-muted);background:color-mix(in srgb,var(--qh-color-ink) 55%,transparent);font-size:12px;cursor:pointer}.chips button:hover,.chips button.active{border-color:var(--qh-color-jade);color:var(--qh-color-ink);background:var(--qh-color-jade)}.input-row>div:last-child{display:grid;grid-template-columns:1fr auto;gap:var(--qh-space-2)}input{min-width:0;padding:10px 12px;border:0;outline:0;color:var(--qh-text);background:transparent;font:inherit}input::placeholder{color:var(--qh-text-muted)}.input-row button[type=submit]{padding:0 15px;border:0;border-radius:var(--qh-radius-sm);color:var(--qh-color-ink);background:var(--qh-color-jade);font-weight:800;cursor:pointer}@media(max-width:700px){main{padding-top:var(--qh-space-5)}.recommendations,.progress{margin-left:0}.recommendation-grid{grid-template-columns:1fr}.dialogue{gap:var(--qh-space-2)}.user-bubble{width:88%}}@media(prefers-reduced-motion:reduce){.immersive-layer{clip-path:none!important}}
</style>
